const int BUZZER = 10;
const int KEYS[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int NOTES[] = {{p:octave}}
const char* NAMES[] = {{p:names}}
int playing = -1;  // which key is sounding; −1 means none

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 8; i++) {
    pinMode(KEYS[i], INPUT_PULLUP);  // the 328P's own pull-up: no resistor needed
  }
}

void loop() {
  int pressed = -1;
  for (int i = 0; i < 8; i++) {
    if (digitalRead(KEYS[i]) == LOW) pressed = i;  // with a pull-up, pressed reads LOW
  }
  if (pressed != playing) {
    playing = pressed;
    if (playing >= 0) {
      tone(BUZZER, NOTES[playing]);
      Serial.println(NAMES[playing]);
    } else {
      noTone(BUZZER);
    }
  }
}

